"""Application service for Production Quality / Foto Finish."""
from __future__ import annotations

from typing import Any
from uuid import UUID

from core.rbac_sql.service import RBACSQLService
from core.utils.operational_window import get_operational_window

from .repository import ProductionQualityRepository


class ProductionQualityAccessDenied(Exception):
    pass


class ProductionQualityNotFound(Exception):
    pass


class ProductionQualityConflict(Exception):
    pass


class ProductionQualityService:
    def __init__(self, repository: ProductionQualityRepository | None = None):
        self.repository = repository or ProductionQualityRepository()

    def _usuario_id(self, current_user: dict) -> int:
        public_uuid = str(
            current_user.get("id")
            or current_user.get("usuario_id")
            or ""
        ).strip()

        if not public_uuid:
            raise ProductionQualityAccessDenied("USER_ID_MISSING")

        usuario_id = self.repository.resolve_usuario_id(public_uuid)

        if not usuario_id:
            raise ProductionQualityAccessDenied("CANONICAL_USER_NOT_FOUND")

        return usuario_id

    def _ensure_scope(
        self,
        current_user: dict,
        empresa_id: int,
        unidad_negocio_id: UUID,
    ) -> int:
        usuario_id = self._usuario_id(current_user)

        if not RBACSQLService.can_access_empresa(
            usuario_id,
            empresa_id,
        ):
            raise ProductionQualityAccessDenied(
                "EMPRESA_SCOPE_DENIED"
            )

        if not RBACSQLService.can_access_unidad(
            usuario_id,
            str(unidad_negocio_id),
        ):
            raise ProductionQualityAccessDenied(
                "UNIDAD_SCOPE_DENIED"
            )

        return usuario_id

    def _assert_item_scope(
        self,
        production_item_id: UUID,
        empresa_id: int,
        unidad_negocio_id: UUID,
    ) -> dict:
        item = self.repository.get_item_scope(
            production_item_id
        )

        if not item:
            raise ProductionQualityNotFound(
                "PRODUCTION_ITEM_NOT_FOUND"
            )

        if int(item["EmpresaID"]) != int(empresa_id):
            raise ProductionQualityAccessDenied(
                "ITEM_EMPRESA_SCOPE_MISMATCH"
            )

        if str(item["UnidadNegocioID"]).lower() != str(
            unidad_negocio_id
        ).lower():
            raise ProductionQualityAccessDenied(
                "ITEM_UNIDAD_SCOPE_MISMATCH"
            )

        return item

    def _fecha_operacion(self, unidad_negocio_id: UUID):
        window = get_operational_window(
            str(unidad_negocio_id)
        )
        return window.fecha_operacion

    def list_items(
        self,
        current_user: dict,
        empresa_id: int,
        unidad_negocio_id: UUID,
        limit: int,
        offset: int,
    ) -> list[dict]:
        self._ensure_scope(
            current_user,
            empresa_id,
            unidad_negocio_id,
        )

        return self.repository.list_items(
            empresa_id,
            unidad_negocio_id,
            self._fecha_operacion(unidad_negocio_id),
            limit,
            offset,
        )

    def list_standards(
        self,
        current_user: dict,
        empresa_id: int,
        unidad_negocio_id: UUID,
    ) -> list[dict]:
        self._ensure_scope(
            current_user,
            empresa_id,
            unidad_negocio_id,
        )

        return self.repository.list_standards(
            empresa_id,
            unidad_negocio_id,
        )

    def list_devices(
        self,
        current_user: dict,
        empresa_id: int,
        unidad_negocio_id: UUID,
    ) -> list[dict]:
        self._ensure_scope(
            current_user,
            empresa_id,
            unidad_negocio_id,
        )

        return self.repository.list_devices(
            empresa_id,
            unidad_negocio_id,
        )

    def create_measurement(
        self,
        current_user: dict,
        payload: dict,
    ) -> dict:
        usuario_id = self._ensure_scope(
            current_user,
            payload["empresa_id"],
            payload["unidad_negocio_id"],
        )

        self._assert_item_scope(
            payload["production_item_id"],
            payload["empresa_id"],
            payload["unidad_negocio_id"],
        )

        return self.repository.create_measurement(
            payload,
            usuario_id,
            self._fecha_operacion(
                payload["unidad_negocio_id"]
            ),
        )

    def create_evidence(
        self,
        current_user: dict,
        payload: dict,
    ) -> dict:
        usuario_id = self._ensure_scope(
            current_user,
            payload["empresa_id"],
            payload["unidad_negocio_id"],
        )

        self._assert_item_scope(
            payload["production_item_id"],
            payload["empresa_id"],
            payload["unidad_negocio_id"],
        )

        return self.repository.create_evidence(
            payload,
            usuario_id,
            self._fecha_operacion(
                payload["unidad_negocio_id"]
            ),
        )

    def create_decision(
        self,
        current_user: dict,
        payload: dict,
    ) -> dict:
        usuario_id = self._ensure_scope(
            current_user,
            payload["empresa_id"],
            payload["unidad_negocio_id"],
        )

        self._assert_item_scope(
            payload["production_item_id"],
            payload["empresa_id"],
            payload["unidad_negocio_id"],
        )

        return self.repository.create_decision(
            payload,
            usuario_id,
        )

    def create_action(
        self,
        current_user: dict,
        payload: dict,
    ) -> dict:
        usuario_id = self._ensure_scope(
            current_user,
            payload["empresa_id"],
            payload["unidad_negocio_id"],
        )

        self._assert_item_scope(
            payload["production_item_id"],
            payload["empresa_id"],
            payload["unidad_negocio_id"],
        )

        return self.repository.create_action(
            payload,
            usuario_id,
        )

    def create_calibration(
        self,
        current_user: dict,
        payload: dict,
    ) -> dict:
        usuario_id = self._ensure_scope(
            current_user,
            payload["empresa_id"],
            payload["unidad_negocio_id"],
        )

        return self.repository.create_calibration(
            payload,
            usuario_id,
        )

"""FastAPI routes for Production Quality / Foto Finish."""
from __future__ import annotations

from uuid import UUID

from fastapi import APIRouter, Depends, HTTPException, Query

from core.rbac.middleware import require_explicit_permission_dual

from .schemas import (
    DeviceCalibrationCreate,
    EvidenceCreate,
    MeasurementCreate,
    QualityActionCreate,
    QualityDecisionCreate,
)
from .service import (
    ProductionQualityAccessDenied,
    ProductionQualityNotFound,
    ProductionQualityService,
)


router = APIRouter(
    prefix="/production-quality",
    tags=["Production Quality"],
)


CAN_VIEW_EXECUTION = require_explicit_permission_dual(
    "production_quality.execution_VER"
)
CAN_CAPTURE = require_explicit_permission_dual(
    "production_quality.execution_GESTIONAR"
)
CAN_CAPTURE_EVIDENCE = require_explicit_permission_dual(
    "production_quality.evidence_CREAR"
)
CAN_VIEW_STANDARDS = require_explicit_permission_dual(
    "production_quality.standards_VER"
)
CAN_DECIDE = require_explicit_permission_dual(
    "production_quality.decisions_AUTORIZAR"
)
CAN_REWORK = require_explicit_permission_dual(
    "production_quality.rework_GESTIONAR"
)
CAN_OVERRIDE = require_explicit_permission_dual(
    "production_quality.override_AUTORIZAR"
)
CAN_VIEW_DEVICES = require_explicit_permission_dual(
    "production_quality.devices_VER"
)
CAN_CONFIGURE_DEVICES = require_explicit_permission_dual(
    "production_quality.devices_CONFIGURAR"
)


def get_service() -> ProductionQualityService:
    return ProductionQualityService()


def _payload_dict(payload):
    if hasattr(payload, "model_dump"):
        return payload.model_dump()
    return payload.dict()


def _translate_error(exc: Exception):
    if isinstance(exc, ProductionQualityAccessDenied):
        raise HTTPException(
            status_code=403,
            detail={
                "code": str(exc),
                "message": "Acceso fuera del alcance RBAC canónico.",
            },
        ) from exc

    if isinstance(exc, ProductionQualityNotFound):
        raise HTTPException(
            status_code=404,
            detail={
                "code": str(exc),
                "message": "Entidad Production Quality no encontrada.",
            },
        ) from exc

    raise exc


@router.get("/items")
def list_items(
    empresa_id: int = Query(gt=0),
    unidad_negocio_id: UUID = Query(),
    limit: int = Query(default=100, ge=1, le=500),
    offset: int = Query(default=0, ge=0),
    current_user: dict = Depends(CAN_VIEW_EXECUTION),
    service: ProductionQualityService = Depends(get_service),
):
    try:
        return {
            "items": service.list_items(
                current_user,
                empresa_id,
                unidad_negocio_id,
                limit,
                offset,
            ),
            "empresa_id": empresa_id,
            "unidad_negocio_id": str(unidad_negocio_id),
        }
    except Exception as exc:
        _translate_error(exc)


@router.get("/standards")
def list_standards(
    empresa_id: int = Query(gt=0),
    unidad_negocio_id: UUID = Query(),
    current_user: dict = Depends(CAN_VIEW_STANDARDS),
    service: ProductionQualityService = Depends(get_service),
):
    try:
        return {
            "items": service.list_standards(
                current_user,
                empresa_id,
                unidad_negocio_id,
            )
        }
    except Exception as exc:
        _translate_error(exc)


@router.get("/devices")
def list_devices(
    empresa_id: int = Query(gt=0),
    unidad_negocio_id: UUID = Query(),
    current_user: dict = Depends(CAN_VIEW_DEVICES),
    service: ProductionQualityService = Depends(get_service),
):
    try:
        return {
            "items": service.list_devices(
                current_user,
                empresa_id,
                unidad_negocio_id,
            )
        }
    except Exception as exc:
        _translate_error(exc)


@router.post("/measurements")
def create_measurement(
    payload: MeasurementCreate,
    current_user: dict = Depends(CAN_CAPTURE),
    service: ProductionQualityService = Depends(get_service),
):
    try:
        return service.create_measurement(
            current_user,
            _payload_dict(payload),
        )
    except Exception as exc:
        _translate_error(exc)


@router.post("/evidence")
def create_evidence(
    payload: EvidenceCreate,
    current_user: dict = Depends(CAN_CAPTURE_EVIDENCE),
    service: ProductionQualityService = Depends(get_service),
):
    try:
        return service.create_evidence(
            current_user,
            _payload_dict(payload),
        )
    except Exception as exc:
        _translate_error(exc)


@router.post("/decisions")
def create_decision(
    payload: QualityDecisionCreate,
    current_user: dict = Depends(CAN_DECIDE),
    service: ProductionQualityService = Depends(get_service),
):
    try:
        return service.create_decision(
            current_user,
            _payload_dict(payload),
        )
    except Exception as exc:
        _translate_error(exc)


@router.post("/actions/rework")
def create_rework(
    payload: QualityActionCreate,
    current_user: dict = Depends(CAN_REWORK),
    service: ProductionQualityService = Depends(get_service),
):
    if payload.action_type.value != "REWORK":
        raise HTTPException(
            status_code=422,
            detail="ACTION_TYPE_MUST_BE_REWORK",
        )

    try:
        return service.create_action(
            current_user,
            _payload_dict(payload),
        )
    except Exception as exc:
        _translate_error(exc)


@router.post("/actions/override")
def create_override(
    payload: QualityActionCreate,
    current_user: dict = Depends(CAN_OVERRIDE),
    service: ProductionQualityService = Depends(get_service),
):
    if payload.action_type.value != "OVERRIDE":
        raise HTTPException(
            status_code=422,
            detail="ACTION_TYPE_MUST_BE_OVERRIDE",
        )

    try:
        return service.create_action(
            current_user,
            _payload_dict(payload),
        )
    except Exception as exc:
        _translate_error(exc)


@router.post("/devices/calibrations")
def create_device_calibration(
    payload: DeviceCalibrationCreate,
    current_user: dict = Depends(CAN_CONFIGURE_DEVICES),
    service: ProductionQualityService = Depends(get_service),
):
    try:
        return service.create_calibration(
            current_user,
            _payload_dict(payload),
        )
    except Exception as exc:
        _translate_error(exc)
